"""One-time stage 6.2 record; refuses replay. Preserve all previous issue states."""
from pathlib import Path
import json
import re

root = Path(__file__).resolve().parents[3]
run = Path(__file__).parent
report = "research/stage6-left-forearm-integration-report-2026-10-20.md"
link = f"[Пилот 6.2]({report})"
issues = (root/"ANATOMY_ISSUES.md").read_text(encoding="utf8")
